import { useEffect, useRef, useState } from "react";

export function LessonVideo({ src }) {
  const [isPlaying, setIsPlaying] = useState(false);
  const videoRef = useRef(null);

  // Needed: the video element is outside React's control.
  useEffect(() => {
    if (isPlaying) videoRef.current.play();
    else videoRef.current.pause();
  }, [isPlaying]);

  return (
    <>
      <video ref={videoRef} src={src} onEnded={() => setIsPlaying(false)} />
      <button type="button" onClick={() => setIsPlaying(!isPlaying)}>
        {isPlaying ? "Pause" : "Play"}
      </button>
    </>
  );
}
```

| Situation | Put it in |
|---|---|
| value computed from props/state. | render. |
| response to a click or submit. | event handler. |
| keep an external system matching state. | effect. |
| reset state when a prop changes. | a key, not an effect. |

